joi_block.script:
hold_ticks := 0
if (all(#LivingRoom_Motion).motionSensor_motion ==| false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 601) {
(#LivingRoom_Light).light_moveToBrightness(30.0, 0.0)
        delay(5 MIN)
(#LivingRoom_Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

